import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade's rate as the server sends it: `pct` is a percent with two decimals. */
export type Rate = { grade: string; pct: string };

export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'] as const;

/** The sheet's rates, one per grade that has one, re-read whenever the sheet is loaded. */
export function useRates(sheet: string) {
  return useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`),
    staleTime: 0,
    gcTime: 0,
  });
}

/** A percent the server accepts: 0.00 or more, with up to two decimals. */
export const PCT = /^\d{1,5}(\.\d{1,2})?$/;

/** The rate for each grade that has one; a grade missing here has no rate. */
export function rateByGrade(rates: Rate[]): Map<string, string> {
  return new Map(rates.map((r) => [r.grade, r.pct]));
}

/** "12.34" as a whole number of hundredths (1234n), exactly. */
function hundredths(value: string): bigint {
  const [whole, frac = ''] = value.split('.');
  return BigInt(whole) * 100n + BigInt((frac + '00').slice(0, 2));
}

function format(cents: bigint): string {
  return `${cents / 100n}.${(cents % 100n).toString().padStart(2, '0')}`;
}

/**
 * What is due on `amount` (two decimals) at `pct` percent: amount times pct divided by 100,
 * rounded half up to two decimals, worked in whole numbers so it is exact. In cents, or null
 * when there is no rate.
 */
export function dueCents(amount: string, pct: string | undefined): bigint | null {
  if (pct === undefined) return null;
  // cents * hundredths-of-a-percent is in ten-thousandths of a cent.
  return (hundredths(amount) * hundredths(pct) + 5000n) / 10000n;
}

/** A due in cents as shown: two decimals, or n/a when there is no rate. */
export function showDue(cents: bigint | null): string {
  return cents === null ? 'n/a' : format(cents);
}

/** Dues added up, skipping the n/a ones. */
export function totalDue(dues: Array<bigint | null>): string {
  return format(dues.reduce<bigint>((sum, d) => (d === null ? sum : sum + d), 0n));
}
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { usePeople } from '../people/usePeople';
import { dueCents, rateByGrade, totalDue, useRates } from '../rates/useRates';
import { claimed, counted, useClaims } from './useClaims';

/**
 * The sheet's claimed-total, everyone's counted (OPEN or SETTLED) claims added up, and its due-total, everyone's due-total
 * added up (a person whose grade has no rate is skipped).
 */
function ClaimedTotal({ sheet }: { user: string; sheet: string }) {
  const { data: all = [] } = useClaims(sheet);
  const claims = counted(all);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const pct = rateByGrade(rates);
  const dues = people.map((p) =>
    dueCents(claimed(claims.filter((c) => c.personId === p.id)), pct.get(p.grade)),
  );
  return (
    <>
      <p>
        Claimed in total: <strong data-testid="rollup-claimed-total">{claimed(claims)}</strong>
      </p>
      <p>
        Due in total: <strong data-testid="rollup-due-total">{totalDue(dues)}</strong>
      </p>
    </>
  );
}

export const contribution = SheetPanels.fill({ order: 20, Component: ClaimedTotal });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import type { Person } from '../people/usePeople';
import { dueCents, rateByGrade, showDue, useRates } from '../rates/useRates';
import { AMOUNT, claimed, claimsKey, counted, useClaims, type Claim } from './useClaims';

/**
 * A person's claims: what they have claimed in all and what is due on that at their grade's rate,
 * one form to add a claim or edit the one whose editor is open, and the claims, newest first, each
 * with its due, its status and the buttons to open, settle or void it. Only OPEN and SETTLED claims
 * count toward claimed and the due-total.
 */
function PersonClaims({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const { data: all = [] } = useClaims(sheet);
  const claims = all.filter((c) => c.personId === person.id);
  const { data: rates = [] } = useRates(sheet);
  const pct = rateByGrade(rates).get(person.grade);
  const [editing, setEditing] = useState<number | null>(null);
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [note, setNote] = useState('');
  const [invalid, setInvalid] = useState(false);
  // The claim whose last status change was refused: its row shows the error.
  const [refused, setRefused] = useState<number | null>(null);
  const base = `/api/sheets/${encodeURIComponent(sheet)}`;

  const save = useMutation({
    mutationFn: (c: { id: number | null; amount: string; date: string; note: string }) => {
      const body = { amount: c.amount, date: c.date, note: c.note, user };
      return c.id === null
        ? postJson<Claim>(`${base}/people/${person.id}/claims`, body)
        : putJson<Claim>(`${base}/claims/${c.id}`, body);
    },
    onSuccess: async () => {
      close();
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });

  const changeStatus = useMutation({
    mutationFn: (c: { id: number; action: 'open' | 'settle' | 'void' }) =>
      postJson<Claim>(`${base}/claims/${c.id}/status`, { action: c.action, user }),
    onMutate: () => setRefused(null),
    onError: (_e, c) => setRefused(c.id),
    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
  });

  // An error goes as soon as its form is changed or submitted again, or an editor is opened.
  const clearError = () => {
    save.reset();
    setInvalid(false);
  };
  const close = () => {
    setEditing(null);
    setAmount('');
    setDate('');
    setNote('');
  };
  const open = (c: Claim) => {
    clearError();
    setRefused(null);
    setEditing(c.id);
    setAmount(c.amount);
    setDate(c.date);
    setNote(c.note);
  };
  const cancel = () => {
    clearError();
    close();
  };

  return (
    <>
      <td data-testid="person-claimed">{claimed(counted(claims))}</td>
      <td data-testid="person-due-total">{showDue(dueCents(claimed(counted(claims)), pct))}</td>
      <td>
        <form
          data-testid="claim-form"
          onSubmit={(e) => {
            e.preventDefault();
            if (!AMOUNT.test(amount.trim())) {
              // Refused here, before anything is sent: the store is untouched.
              save.reset();
              setInvalid(true);
              return;
            }
            setInvalid(false);
              {invalid
                ? 'The amount must be 0.00 or more, with up to two decimals.'
                : 'Could not save this claim.'}
            </span>
          )}
        </form>
        <ul data-testid="claim-list">
          {claims.map((c) => (
            <li key={c.id} data-testid={`claim-row-${c.id}`}>
              <span data-testid="claim-amount">{c.amount}</span>{' '}
              <span data-testid="claim-date">{c.date}</span>{' '}
              <span data-testid="claim-note">{c.note}</span>{' '}
              <span data-testid="claim-due">{showDue(dueCents(c.amount, pct))}</span>{' '}
              <span data-testid="claim-number">{c.number ?? ''}</span>{' '}
              <span data-testid="claim-status">{c.status}</span>{' '}
              {(['open', 'settle', 'void'] as const).map((action) => (
                <span key={action}>
                  <button
                    type="button"
                    data-testid={`claim-${action}`}
                    disabled={changeStatus.isPending}
