s=open(f).read()+'''
/** What is due on one claim, in cents: the due fixed when it was settled, or else live at `pct`
 *  (null, n/a, when there is no rate). */
export function claimDueCents(claim: Claim, pct: string | undefined): bigint | null {
  return claim.due !== null ? hundredths(claim.due) : dueCents(claim.amount, pct);
}

/**
 * What is due on these (counted) claims, in cents: the fixed dues added up, plus what is due at
 * `pct` on the rest added up. Null (n/a) when there is no rate and some claim's due is not fixed,
 * or there are no claims at all.
 */
export function dueTotalCents(claims: Claim[], pct: string | undefined): bigint | null {
  const fixed = claims.filter((c) => c.due !== null);
  const live = claims.filter((c) => c.due === null);
  const frozen = fixed.reduce((sum, c) => sum + hundredths(c.due as string), 0n);
  const due = dueCents(claimed(live), pct);
  if (due === null) return fixed.length > 0 && live.length === 0 ? frozen : null;
  return frozen + due;
}
'''
